/*
 * aud_routes.c -- independent audit code for THM-4867 section 3 (failed routes) and background claims.
 * Written from scratch (own canonical form by refinement + individualization; own DPs).
 *
 *   route_a NMAX : all labelled tournaments of orders 4..NMAX; pairs (T, e) with T - e strong; how many are
 *                  non-Hamiltonian.
 *   classes NMAX : all tournament classes of orders 1..NMAX (generated by one-vertex extension + canonical form),
 *                  checked against A000568; then for every class:
 *                   - route (b): 2-arc-strong classes (T - e strong for every arc e) and the arcs e with T - e
 *                     non-Hamiltonian (labelled arcs of the representative, and arc orbits under Aut(T));
 *                   - the "1994 local criterion": for strong T of order >= 7, hc(T) == 1 versus "every strong
 *                     6-vertex subtournament has exactly one Hamiltonian cycle";
 *                   - self-converse classes (A002785);
 *                   - order 5: the classes with scores, H (Hamiltonian paths) and hc, adjacency rows printed.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <omp.h>

typedef unsigned long long u64;
typedef uint32_t msk;
#define MAXN 12

static int popc(msk x) { return __builtin_popcount(x); }

/* ---------- canonical form ---------- */
static int refine(int n, const msk *out, int *col) {
    int k = 0; for (int v = 0; v < n; v++) if (col[v] + 1 > k) k = col[v] + 1;
    for (;;) {
        int sig[MAXN][MAXN + 1];
        for (int v = 0; v < n; v++) {
            sig[v][0] = col[v];
            for (int c = 1; c <= k; c++) sig[v][c] = 0;
            msk o = out[v]; while (o) { int u = __builtin_ctz(o); o &= o - 1; sig[v][col[u] + 1]++; }
        }
        int ord[MAXN]; for (int i = 0; i < n; i++) ord[i] = i;
        for (int i = 1; i < n; i++) { int x = ord[i], j = i - 1; while (j >= 0 && memcmp(sig[ord[j]], sig[x], sizeof(int) * (k + 1)) > 0) { ord[j + 1] = ord[j]; j--; } ord[j + 1] = x; }
        int nk = 0, nc[MAXN];
        for (int i = 0; i < n; i++) { if (i > 0 && memcmp(sig[ord[i]], sig[ord[i - 1]], sizeof(int) * (k + 1))) nk++; nc[ord[i]] = nk; }
        nk++;
        memcpy(col, nc, sizeof(int) * n);
        if (nk == k) return k;
        k = nk;
    }
}
static void csearch(int n, const msk *out, const int *col0, int k, u64 *best, int *have) {
    int col[MAXN]; memcpy(col, col0, sizeof(int) * n);
    if (k == n) {
        int perm[MAXN]; for (int v = 0; v < n; v++) perm[col[v]] = v;
        u64 c = 0;
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) c = (c << 1) | ((out[perm[i]] >> perm[j]) & 1u);
        if (!*have || c < *best) { *best = c; *have = 1; }
        return;
    }
    int size[MAXN] = {0}; for (int v = 0; v < n; v++) size[col[v]]++;
    int tc = -1; for (int c = 0; c < k; c++) if (size[c] > 1) { tc = c; break; }
    for (int v = 0; v < n; v++) {
        if (col[v] != tc) continue;
        int nc[MAXN];
        for (int u = 0; u < n; u++) { if (col[u] < tc) nc[u] = col[u]; else if (col[u] > tc) nc[u] = col[u] + 1; else nc[u] = (u == v) ? tc : tc + 1; }
        int k2 = refine(n, out, nc);
        csearch(n, out, nc, k2, best, have);
    }
}
static u64 canon(int n, const msk *out) {
    int col[MAXN]; for (int v = 0; v < n; v++) col[v] = popc(out[v]);
    /* normalise to 0..k-1 preserving order */
    int vals[MAXN], nv = 0;
    for (int v = 0; v < n; v++) { int f = 0; for (int i = 0; i < nv; i++) if (vals[i] == col[v]) f = 1; if (!f) vals[nv++] = col[v]; }
    for (int i = 1; i < nv; i++) { int x = vals[i], j = i - 1; while (j >= 0 && vals[j] > x) { vals[j + 1] = vals[j]; j--; } vals[j + 1] = x; }
    for (int v = 0; v < n; v++) for (int i = 0; i < nv; i++) if (vals[i] == col[v]) { col[v] = i; break; }
    int k = refine(n, out, col);
    u64 best = 0; int have = 0;
    csearch(n, out, col, k, &best, &have);
    return best;
}
static void decode(int n, u64 c, msk *out) {
    int b = n * (n - 1) / 2 - 1;
    for (int i = 0; i < n; i++) out[i] = 0;
    for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) { int bit = (int)((c >> b) & 1); b--; if (bit) out[i] |= 1u << j; else out[j] |= 1u << i; }
}
static int cmp64(const void *a, const void *b) { u64 x = *(const u64 *)a, y = *(const u64 *)b; return x < y ? -1 : x > y; }

/* ---------- digraph utilities (out masks; a missing pair allowed) ---------- */
static int strong(int n, const msk *out) {
    msk full = (n == 32) ? 0xffffffffu : ((1u << n) - 1);
    msk in[MAXN]; for (int v = 0; v < n; v++) in[v] = 0;
    for (int u = 0; u < n; u++) { msk o = out[u]; while (o) { int v = __builtin_ctz(o); o &= o - 1; in[v] |= 1u << u; } }
    msk r = 1, f = 1; while (f) { msk nx = 0; msk g = f; while (g) { int x = __builtin_ctz(g); g &= g - 1; nx |= out[x]; } nx &= ~r; r |= nx; f = nx; }
    if (r != full) return 0;
    r = 1; f = 1; while (f) { msk nx = 0; msk g = f; while (g) { int x = __builtin_ctz(g); g &= g - 1; nx |= in[x]; } nx &= ~r; r |= nx; f = nx; }
    return r == full;
}
/* Hamiltonian cycle count saturated at 2 (works for any digraph) */
static int hc_sat(int n, const msk *out, msk *d1, msk *d2) {
    if (n == 1) return 0;
    msk in[MAXN]; for (int v = 0; v < n; v++) in[v] = 0;
    for (int u = 0; u < n; u++) { msk o = out[u]; while (o) { int v = __builtin_ctz(o); o &= o - 1; in[v] |= 1u << u; } }
    int full = (1 << n) - 1;
    memset(d1, 0, sizeof(msk) * (size_t)(full + 1)); memset(d2, 0, sizeof(msk) * (size_t)(full + 1));
    d1[1] = 1;
    for (int S = 1; S <= full; S += 2) {
        if (!d1[S]) continue;
        msk e1 = d1[S], e2 = d2[S], rest = (msk)full & ~(msk)S;
        while (rest) {
            int w = __builtin_ctz(rest); rest &= rest - 1;
            msk c1 = e1 & in[w]; if (!c1) continue;
            msk c2 = e2 & in[w]; int T = S | (1 << w);
            d1[T] |= 1u << w; if (c2 || (c1 & (c1 - 1))) d2[T] |= 1u << w;
        }
    }
    msk c1 = d1[full] & in[0], c2 = d2[full] & in[0];
    if (c2 || (c1 & (c1 - 1))) return 2;
    return c1 ? 1 : 0;
}
/* exact Hamiltonian path count of a tournament (small n) */
static long long hpaths(int n, const msk *out) {
    int full = (1 << n) - 1;
    long long *dp = calloc((size_t)(full + 1) * n, sizeof(long long));
    for (int v = 0; v < n; v++) dp[(size_t)(1 << v) * n + v] = 1;
    for (int S = 1; S <= full; S++) for (int v = 0; v < n; v++) {
        long long c = dp[(size_t)S * n + v]; if (!c) continue;
        msk o = out[v] & ~(msk)S; while (o) { int w = __builtin_ctz(o); o &= o - 1; dp[(size_t)(S | (1 << w)) * n + w] += c; }
    }
    long long h = 0; for (int v = 0; v < n; v++) h += dp[(size_t)full * n + v];
    free(dp); return h;
}

/* ---------- route (a): labelled ---------- */
static void route_a(int NMAX) {
    for (int n = 4; n <= NMAX; n++) {
        int pi[64], pj[64], np = 0;
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) { pi[np] = i; pj[np] = j; np++; }
        long long total = 1LL << np, strongpairs = 0, nonham = 0, strongT = 0;
#pragma omp parallel reduction(+:strongpairs, nonham, strongT)
        {
            msk *d1 = malloc(sizeof(msk) << n), *d2 = malloc(sizeof(msk) << n);
#pragma omp for schedule(dynamic, 1024)
            for (long long mask = 0; mask < total; mask++) {
                msk out[MAXN] = {0};
                for (int k = 0; k < np; k++) { if ((mask >> k) & 1) out[pi[k]] |= 1u << pj[k]; else out[pj[k]] |= 1u << pi[k]; }
                if (!strong(n, out)) continue;
                strongT++;
                for (int k = 0; k < np; k++) {
                    msk o2[MAXN]; memcpy(o2, out, sizeof(msk) * n);
                    o2[pi[k]] &= ~(1u << pj[k]); o2[pj[k]] &= ~(1u << pi[k]);
                    if (!strong(n, o2)) continue;
                    strongpairs++;
                    if (hc_sat(n, o2, d1, d2) == 0) nonham++;
                }
            }
            free(d1); free(d2);
        }
        printf("ROUTE_A n=%d: labelled tournaments %lld, strong %lld; pairs (T, e) with T - e strong: %lld, of which non-Hamiltonian: %lld\n",
               n, total, strongT, strongpairs, nonham);
        fflush(stdout);
    }
}

/* ---------- classes ---------- */
static u64 *gen_level(int n, const u64 *prev, size_t np, size_t *cnt) {
    int m = n - 1;
    size_t cand = np << m;
    u64 *buf = malloc(sizeof(u64) * (cand + 1));
#pragma omp parallel for schedule(dynamic, 16)
    for (long r = 0; r < (long)np; r++) {
        msk o[MAXN]; decode(m, prev[r], o);
        for (msk S = 0; S < (1u << m); S++) {
            msk t[MAXN];
            for (int i = 0; i < m; i++) t[i] = o[i] | (((S >> i) & 1) ? 0 : (1u << m));
            t[m] = S;
            buf[(size_t)r * (1u << m) + S] = canon(n, t);
        }
    }
    qsort(buf, cand, sizeof(u64), cmp64);
    size_t k = 0; for (size_t i = 0; i < cand; i++) if (k == 0 || buf[i] != buf[k - 1]) buf[k++] = buf[i];
    *cnt = k;
    return buf;
}

static int is_aut(int n, const msk *out, const int *p) {
    for (int u = 0; u < n; u++) for (int v = 0; v < n; v++) if (u != v && (((out[u] >> v) & 1) != ((out[p[u]] >> p[v]) & 1))) return 0;
    return 1;
}
static int next_perm(int *a, int n) {
    int i = n - 2; while (i >= 0 && a[i] >= a[i + 1]) i--; if (i < 0) return 0;
    int j = n - 1; while (a[j] <= a[i]) j--; int t = a[i]; a[i] = a[j]; a[j] = t;
    for (int l = i + 1, r = n - 1; l < r; l++, r--) { t = a[l]; a[l] = a[r]; a[r] = t; }
    return 1;
}

static void classes(int NMAX) {
    const long long A000568[] = {1, 1, 1, 2, 4, 12, 56, 456, 6880, 191536, 9733056};
    u64 *lev[MAXN + 1]; size_t cnt[MAXN + 1];
    lev[1] = malloc(sizeof(u64)); lev[1][0] = 0; cnt[1] = 1;
    for (int n = 2; n <= NMAX; n++) {
        double t0 = omp_get_wtime();
        lev[n] = gen_level(n, lev[n - 1], cnt[n - 1], &cnt[n]);
        printf("CLASSES n=%d: %zu (A000568: %lld) [%.1f s]\n", n, cnt[n], A000568[n], omp_get_wtime() - t0);
        fflush(stdout);
    }
    for (int n = 3; n <= NMAX; n++) {
        long long nstrong = 0, twoarc = 0, badpairs = 0, badclasses = 0, selfconv = 0;
        long long uh = 0, loc_ok = 0, disagree_uh_notloc = 0, disagree_loc_notuh = 0, nstrong_hc1 = 0;
        long long ex_loc_notuh = -1, ex_uh_notloc = -1;
        u64 *bad_codes = malloc(sizeof(u64) * 64); int nbad = 0;
#pragma omp parallel reduction(+:nstrong, twoarc, badpairs, badclasses, selfconv, uh, loc_ok, disagree_uh_notloc, disagree_loc_notuh)
        {
            msk *d1 = malloc(sizeof(msk) << n), *d2 = malloc(sizeof(msk) << n);
#pragma omp for schedule(dynamic, 64)
            for (long r = 0; r < (long)cnt[n]; r++) {
                msk o[MAXN]; decode(n, lev[n][r], o);
                /* self-converse */
                msk oc[MAXN]; for (int v = 0; v < n; v++) oc[v] = 0;
                for (int u = 0; u < n; u++) for (int v = 0; v < n; v++) if ((o[u] >> v) & 1) oc[v] |= 1u << u;
                if (canon(n, oc) == lev[n][r]) selfconv++;
                if (!strong(n, o)) continue;
                nstrong++;
                /* route (b) */
                int all2 = 1;
                for (int u = 0; u < n && all2; u++) { msk g = o[u]; while (g) { int v = __builtin_ctz(g); g &= g - 1; msk o2[MAXN]; memcpy(o2, o, sizeof(msk) * n); o2[u] &= ~(1u << v); if (!strong(n, o2)) { all2 = 0; break; } } }
                if (all2) {
                    twoarc++;
                    int nb = 0;
                    for (int u = 0; u < n; u++) { msk g = o[u]; while (g) { int v = __builtin_ctz(g); g &= g - 1; msk o2[MAXN]; memcpy(o2, o, sizeof(msk) * n); o2[u] &= ~(1u << v); if (hc_sat(n, o2, d1, d2) == 0) nb++; } }
                    if (nb) {
                        badpairs += nb; badclasses++;
#pragma omp critical
                        { if (nbad < 64) bad_codes[nbad++] = lev[n][r]; }
                    }
                }
                /* local criterion */
                int hc = hc_sat(n, o, d1, d2);
                if (hc == 1) uh++;
                if (n >= 7) {
                    int ok = 1;
                    for (msk S = 0; S < (1u << n) && ok; S++) {
                        if (popc(S) != 6) continue;
                        int idx[MAXN], k = 0; for (int v = 0; v < n; v++) if ((S >> v) & 1) idx[k++] = v;
                        msk s6[MAXN];
                        for (int i = 0; i < 6; i++) { s6[i] = 0; for (int j = 0; j < 6; j++) if ((o[idx[i]] >> idx[j]) & 1) s6[i] |= 1u << j; }
                        if (!strong(6, s6)) continue;
                        if (hc_sat(6, s6, d1, d2) != 1) ok = 0;
                    }
                    if (ok) loc_ok++;
                    if (hc == 1 && !ok) {
                        disagree_uh_notloc++;
#pragma omp critical
                        { if (ex_uh_notloc < 0) ex_uh_notloc = r; }
                    }
                    if (hc != 1 && ok) {
                        disagree_loc_notuh++;
#pragma omp critical
                        { if (ex_loc_notuh < 0) ex_loc_notuh = r; }
                    }
                }
            }
            free(d1); free(d2);
        }
        (void)nstrong_hc1;
        printf("n=%d: classes %zu, strong %lld, self-converse %lld, uniquely Hamiltonian %lld | 2-arc-strong %lld, (class, arc) pairs with T - e non-Hamiltonian %lld in %lld classes\n",
               n, cnt[n], nstrong, selfconv, uh, twoarc, badpairs, badclasses);
        if (n >= 7) {
            printf("   local criterion (strong T, every strong 6-subtournament uniquely Hamiltonian): holds in %lld strong classes; uniquely Hamiltonian but criterion fails: %lld; criterion holds but hc != 1: %lld\n",
                   loc_ok, disagree_uh_notloc, disagree_loc_notuh);
            if (ex_loc_notuh >= 0) {
                msk o[MAXN]; decode(n, lev[n][ex_loc_notuh], o);
                msk *d1 = malloc(sizeof(msk) << n), *d2 = malloc(sizeof(msk) << n);
                printf("   example (criterion holds, hc = %s): out-rows", hc_sat(n, o, d1, d2) == 2 ? ">=2" : "0");
                for (int v = 0; v < n; v++) printf(" %u", o[v]); printf("\n");
                free(d1); free(d2);
            }
            if (ex_uh_notloc >= 0) {
                msk o[MAXN]; decode(n, lev[n][ex_uh_notloc], o);
                printf("   example (uniquely Hamiltonian, criterion fails): out-rows"); for (int v = 0; v < n; v++) printf(" %u", o[v]); printf("\n");
            }
        }
        for (int b = 0; b < nbad; b++) {
            msk o[MAXN]; decode(n, bad_codes[b], o);
            int sc[MAXN]; for (int v = 0; v < n; v++) sc[v] = popc(o[v]);
            printf("   bad class %d: out-rows", b); for (int v = 0; v < n; v++) printf(" %u", o[v]);
            printf(" | scores"); for (int v = 0; v < n; v++) printf(" %d", sc[v]);
            /* automorphisms by brute force */
            int p[MAXN]; for (int i = 0; i < n; i++) p[i] = i;
            int auts[400][MAXN]; int na = 0;
            do { int okp = 1; for (int v = 0; v < n; v++) if (sc[p[v]] != sc[v]) { okp = 0; break; } if (okp && is_aut(n, o, p)) { if (na < 400) memcpy(auts[na], p, sizeof(int) * n); na++; } } while (next_perm(p, n));
            /* bad arcs and their orbits */
            msk *d1 = malloc(sizeof(msk) << n), *d2 = malloc(sizeof(msk) << n);
            int bu[64], bv[64], nb = 0;
            for (int u = 0; u < n; u++) { msk g = o[u]; while (g) { int v = __builtin_ctz(g); g &= g - 1; msk o2[MAXN]; memcpy(o2, o, sizeof(msk) * n); o2[u] &= ~(1u << v); if (hc_sat(n, o2, d1, d2) == 0) { bu[nb] = u; bv[nb] = v; nb++; } } }
            int orb = 0, seen[64] = {0};
            for (int i = 0; i < nb; i++) { if (seen[i]) continue; orb++; for (int a = 0; a < na && a < 400; a++) { int x = auts[a][bu[i]], y = auts[a][bv[i]]; for (int j = 0; j < nb; j++) if (bu[j] == x && bv[j] == y) seen[j] = 1; } }
            printf(" | |Aut| = %d, bad arcs:", na); for (int i = 0; i < nb; i++) printf(" %d->%d", bu[i], bv[i]);
            printf(" (%d orbit(s)); H = %lld, hc(T) = %s\n", orb, hpaths(n, o), hc_sat(n, o, d1, d2) == 2 ? ">=2" : "1");
            free(d1); free(d2);
        }
        if (n == 5) {
            msk *d1 = malloc(sizeof(msk) << n), *d2 = malloc(sizeof(msk) << n);
            for (size_t r = 0; r < cnt[n]; r++) {
                msk o[MAXN]; decode(n, lev[n][r], o);
                if (!strong(n, o)) continue;
                /* exact hc by brute force over cyclic orders starting at 0 */
                int p[5] = {0, 1, 2, 3, 4}; int hcx = 0;
                do { if (p[0] != 0) break; int okc = 1; for (int i = 0; i < 5; i++) if (!((o[p[i]] >> p[(i + 1) % 5]) & 1)) { okc = 0; break; } hcx += okc; } while (next_perm(p, 5));
                printf("   order-5 strong class: out-rows"); for (int v = 0; v < n; v++) printf(" %u", o[v]);
                printf(" | scores"); for (int v = 0; v < n; v++) printf(" %d", popc(o[v]));
                printf(" | H = %lld, hc = %d\n", hpaths(n, o), hcx);
            }
            free(d1); free(d2);
        }
        fflush(stdout);
        free(bad_codes);
    }
}

int main(int argc, char **argv) {
    printf("aud_routes threads=%d\n", omp_get_max_threads());
    if (argc >= 3 && !strcmp(argv[1], "route_a")) route_a(atoi(argv[2]));
    if (argc >= 3 && !strcmp(argv[1], "classes")) classes(atoi(argv[2]));
    return 0;
}
